package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class RomanYearsTest {
 private int independent(String s){int sum=0,last=0;for(int i=s.length()-1;i>=0;i--){int value=switch(s.charAt(i)){case 'I'->1;case 'V'->5;case 'X'->10;case 'L'->50;case 'C'->100;case 'D'->500;case 'M'->1000;default->throw new AssertionError(s);};sum+=value<last?-value:value;last=value;}return sum;}
 @Test public void allCanonicalNumeralsAndYearsUsePublicSymbols(){for(String id:List.of(RomanRead.ID,RomanRead.YEAR)){int maximum=id.equals(RomanRead.ID)?1000:3999;Set<String> seen=new HashSet<>();for(int n=1;n<=maximum;n++){Question q=id.equals(RomanRead.ID)?RomanRead.make(n):RomanRead.makeYear(n);assertTrue(seen.add(q.signature()));assertEquals(n,independent(RomanRead.displayed(q.prompt)));q.answers=new String[]{"99999"};q.expression="99999";assertTrue(new Checker().check(q,List.of(),List.of(""+n)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(n+1))).status);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));String[] groups=RomanRead.groups(RomanRead.numeral(n));int sum=0;for(int i=0;i<groups.length;i++){int value=independent(groups[i]);sum+=value;assertTrue(h.step(i).accepts(""+value));assertFalse(h.step(i).before.matches("(?s).*[0-9].*"));}assertEquals(n,sum);assertTrue(h.step(groups.length).accepts(""+n));}}assertEquals("M",RomanRead.numeral(1000));assertEquals("MMXXVI",RomanRead.numeral(2026));assertEquals("MMMCMXCIX",RomanRead.numeral(3999));}
 @Test public void actualSelectedDomainsExhaustBeforeOldestAndEarlierGradeStaysSmall(){Generator g=new Generator(new Random(156));for(String id:List.of(RomanRead.ID,RomanRead.YEAR)){int count=id.equals(RomanRead.ID)?1000:3999;List<String> recent=new ArrayList<>();CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",id,5);for(int i=0;i<count;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertNotNull(RomanRead.read(q));assertTrue(q.choices.isEmpty());}assertEquals(recent.get(0),g.next(id,recent,false,limits).signature());}for(int i=0;i<200;i++)assertTrue(RomanRead.read(g.next(RomanRead.ID,List.of(),false,GlobalCurriculum.limits("england-primary-2021-v1",RomanRead.ID,4)))<=100);assertFalse(Curriculum.inCurriculum(Catalog.get(RomanRead.YEAR),2022));}
 @Test public void malformedYearsAndWrongHeadersCannotUseKeys(){for(String s:List.of("IIII","IIV","IC","XM","MMMM","iv","0","","Ⅰ")){Question q=RomanRead.makeYear(2026);q.prompt=RomanRead.YEAR_PROMPT+"\n"+s;assertNull(RomanRead.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("2026")).status);}Question q=RomanRead.makeYear(2026);q.prompt=RomanRead.PROMPT+"\nMMXXVI";assertNull(RomanRead.read(q));q=RomanRead.make(1000);q.prompt=RomanRead.PROMPT+"\nMCI";assertNull(RomanRead.read(q));}
}
